#!/usr/bin/env node
'use strict';

/**
 * V2-07-FIX L3b — PreToolUse Violation Gate
 *
 * Reads `.claude/violation-block-list.json` (auto-generated by check-violation-recurrence.cjs)
 * and blocks Edit / Write / NotebookEdit tool calls whose target file matches any
 * blocked rule's scope_globs.
 *
 * Exit codes:
 *   0 = allow (default)
 *   2 = block (write stderr message; PreToolUse contract: exit 2 → user sees stderr)
 *
 * Fail-open: any error / missing block-list / parse failure → exit 0
 *            (PreToolUse hook should NEVER break workflow on internal error)
 *
 * Memory id=3964 (CEO 2026-05-07 雙決策 - PreToolUse 立即啟用)
 */

const fs = require('node:fs');
const path = require('node:path');

const PROJECT_ROOT = path.resolve(__dirname, '..', '..');
const BLOCK_LIST_PATH = path.join(PROJECT_ROOT, '.claude', 'violation-block-list.json');
const STDIN_TIMEOUT_MS = 1000;
const MAX_STDIN_BYTES = 256 * 1024;

// ── Glob match helper (subset: ** / * / ?) ──────────────────────────

function matchesScope(filePath, scopeGlobs) {
  if (!filePath || !Array.isArray(scopeGlobs) || scopeGlobs.length === 0) return false;
  const normalized = String(filePath).replace(/\\/g, '/');
  for (const glob of scopeGlobs) {
    if (typeof glob !== 'string' || !glob) continue;
    const re = new RegExp('^' + glob
      .replace(/\./g, '\\.')
      .replace(/\*\*/g, '__DBLSTAR__')
      .replace(/\*/g, '[^/]*')
      .replace(/__DBLSTAR__/g, '.*')
      .replace(/\?/g, '.')
      + '$');
    if (re.test(normalized)) return true;
  }
  return false;
}

// ── Stdin reader (timeout + max bytes) ──────────────────────────────

function readStdin() {
  return new Promise(resolve => {
    if (process.stdin.isTTY) { resolve(''); return; }
    let data = '';
    let bytes = 0;
    const timer = setTimeout(() => {
      try { process.stdin.removeAllListeners(); process.stdin.pause(); } catch { /* ignore */ }
      resolve(data);
    }, STDIN_TIMEOUT_MS);
    try { process.stdin.setEncoding('utf8'); } catch { /* ignore */ }
    process.stdin.on('data', chunk => {
      bytes += Buffer.byteLength(chunk, 'utf8');
      if (bytes < MAX_STDIN_BYTES) data += chunk;
    });
    process.stdin.on('end', () => { clearTimeout(timer); resolve(data); });
    process.stdin.on('error', () => { clearTimeout(timer); resolve(''); });
  });
}

// ── BOM-safe JSON parse ─────────────────────────────────────────────

function parseJsonStripBom(raw) {
  if (!raw) return null;
  const trimmed = raw.charCodeAt(0) === 0xFEFF ? raw.slice(1) : raw;
  try { return JSON.parse(trimmed); } catch { return null; }
}

// ── Main ────────────────────────────────────────────────────────────

async function main() {
  // 1. Block-list missing → allow
  if (!fs.existsSync(BLOCK_LIST_PATH)) process.exit(0);

  let blockList;
  try {
    blockList = parseJsonStripBom(fs.readFileSync(BLOCK_LIST_PATH, 'utf8'));
  } catch { process.exit(0); }

  if (!blockList || !Array.isArray(blockList.blocked_rules) || blockList.blocked_rules.length === 0) {
    process.exit(0);
  }

  // 2. Read stdin (tool_name + tool_input.file_path)
  let raw;
  try { raw = await readStdin(); } catch { process.exit(0); }
  const input = parseJsonStripBom(raw) || {};

  const toolName = input.tool_name;
  const toolInput = input.tool_input || {};

  // 3. Only check Edit / Write / NotebookEdit (Bash/Read/Grep/Glob 不檢查)
  if (!['Edit', 'Write', 'NotebookEdit'].includes(toolName)) process.exit(0);

  const filePath = toolInput.file_path || toolInput.notebook_path;
  if (!filePath) process.exit(0);

  // 4. Iterate blocked rules → first scope match → BLOCK
  for (const blocked of blockList.blocked_rules) {
    if (matchesScope(filePath, blocked.scope_globs)) {
      const lines = [
        '',
        '🔴 PreToolUse 違規攔截 (V2-07-FIX BLOCK)',
        '',
        `Rule: ${blocked.rule_path}`,
        `7d 累積: ${blocked.current_count_7d} 次 (≥${blockList.policy && blockList.policy.block_count_threshold || 5} 自動 BLOCK)`,
        `Blocked since: ${blocked.blocked_since}`,
        `File: ${filePath}`,
        '',
        blocked.exit_message || '請先解決違規再 commit。',
        '',
        '解除方式: 該 rule 7d 累積數降至 < 5 次後,下次 check-violation-recurrence.cjs 自動移除。',
        '',
      ].join('\n');
      try { process.stderr.write(lines); } catch { /* ignore */ }
      process.exit(2);
    }
  }

  // 5. No match → allow
  process.exit(0);
}

main().catch(() => process.exit(0));  // fail-open
